  ('fc1-1', 'f-consonants-1', 'character', 'ㄱ', 'g/k · giyeok', 'Konsonan g/k', 'The g/k consonant', 'Di awal suku kata terdengar lembut seperti g; di akhir lebih dekat ke k.', 'At the start it is a light g; at the end it is closer to k.', 'Nama huruf ini 기역 (giyeok).', 'Its name is 기역 (giyeok).', '가 · 고 · 국', 'ga, go, dan guk', 'ga, go, and guk', NULL, 1),
  ('fc1-2', 'f-consonants-1', 'character', 'ㄴ', 'n · nieun', 'Konsonan n', 'The n consonant', 'Sentuhkan ujung lidah di belakang gigi atas.', 'Touch the tip of your tongue behind your upper teeth.', 'Nama huruf ini 니은 (nieun).', 'Its name is 니은 (nieun).', '나 · 너 · 눈', 'na, neo, dan nun', 'na, neo, and nun', NULL, 2),
  ('fc1-3', 'f-consonants-1', 'character', 'ㅁ', 'm · mieum', 'Konsonan m', 'The m consonant', 'Tutup kedua bibir seperti bunyi m.', 'Close both lips, just like an m.', 'Nama huruf ini 미음 (mieum).', 'Its name is 미음 (mieum).', '마 · 모 · 몸', 'ma, mo, dan mom', 'ma, mo, and mom', NULL, 3),
  ('fc1-4', 'f-consonants-1', 'character', 'ㅅ', 's · siot', 'Konsonan s', 'The s consonant', 'Di depan ㅣ, bunyinya menjadi lebih dekat ke "sy".', 'Before ㅣ, the sound becomes closer to "sh".', 'Nama huruf ini 시옷 (siot).', 'Its name is 시옷 (siot).', '사 · 소 · 시', 'sa, so, dan si', 'sa, so, and si', NULL, 4),

  ('fc2-1', 'f-consonants-2', 'character', 'ㅎ', 'h · hieut', 'Konsonan h', 'The h consonant', 'Hembuskan udara ringan saat mengucapkan h.', 'Release a light breath as you say h.', 'Nama huruf ini 히읗 (hieut).', 'Its name is 히읗 (hieut).', '하 · 호 · 한', 'ha, ho, dan han', 'ha, ho, and han', NULL, 1),
  ('fc2-2', 'f-consonants-2', 'character', 'ㄷ', 'd/t · digeut', 'Konsonan d/t', 'The d/t consonant', 'Di awal terdengar seperti d ringan dan di akhir seperti t pendek.', 'At the start it is a light d; at the end it is a short t.', 'Nama huruf ini 디귿 (digeut).', 'Its name is 디귿 (digeut).', '다 · 도 · 닫', 'da, do, dan dat', 'da, do, and dat', NULL, 2),
  ('fc2-3', 'f-consonants-2', 'character', 'ㄹ', 'r/l · rieul', 'Konsonan r/l', 'The r/l consonant', 'Di antara vokal terdengar seperti r ringan; di akhir mendekati l.', 'Between vowels it is a light r; at the end it is closer to l.', 'Nama huruf ini 리을 (rieul).', 'Its name is 리을 (rieul).', '라 · 로 · 말', 'ra, ro, dan mal', 'ra, ro, and mal', NULL, 3),
  ('fc2-4', 'f-consonants-2', 'character', 'ㅂ', 'b/p · bieup', 'Konsonan b/p', 'The b/p consonant', 'Awali dengan b lembut; batchim-nya terdengar seperti p pendek.', 'Begin with a soft b; as batchim it sounds like a short p.', 'Nama huruf ini 비읍 (bieup).', 'Its name is 비읍 (bieup).', '바 · 보 · 밥', 'ba, bo, dan bap', 'ba, bo, and bap', NULL, 4),
  ('fc2-5', 'f-consonants-2', 'character', 'ㅇ', 'silent/ng · ieung', 'Konsonan diam/ng', 'The silent/ng consonant', 'Diam di awal suku kata dan berbunyi ng sebagai batchim.', 'It is silent at the start and sounds ng as batchim.', 'Nama huruf ini 이응 (ieung).', 'Its name is 이응 (ieung).', '아 · 오 · 강', 'a, o, dan gang', 'a, o, and gang', NULL, 5),
  ('fc2-6', 'f-consonants-2', 'character', 'ㅈ', 'j · jieut', 'Konsonan j', 'The j consonant', 'Ucapkan j dengan pelepasan udara yang ringan.', 'Say j with a light release of air.', 'Nama huruf ini 지읒 (jieut).', 'Its name is 지읒 (jieut).', '자 · 조 · 집', 'ja, jo, dan jip', 'ja, jo, and jip', NULL, 6),
  ('fc2-7', 'f-consonants-2', 'character', 'ㅊ', 'ch · chieut', 'Konsonan ch', 'The ch consonant', 'Bunyinya seperti j dengan hembusan udara lebih kuat.', 'It sounds like j with a stronger puff of air.', 'Nama huruf ini 치읓 (chieut).', 'Its name is 치읓 (chieut).', '차 · 초 · 춤', 'cha, cho, dan chum', 'cha, cho, and chum', NULL, 7),
  ('fc2-8', 'f-consonants-2', 'character', 'ㅋ', 'k · kieuk', 'Konsonan k', 'The k consonant', 'Lepaskan udara lebih kuat daripada ㄱ.', 'Release more air than with ㄱ.', 'Nama huruf ini 키읔 (kieuk).', 'Its name is 키읔 (kieuk).', '카 · 코 · 키', 'ka, ko, dan ki', 'ka, ko, and ki', NULL, 8),
  ('fc2-9', 'f-consonants-2', 'character', 'ㅌ', 't · tieut', 'Konsonan t', 'The t consonant', 'Lepaskan udara lebih kuat daripada ㄷ.', 'Release more air than with ㄷ.', 'Nama huruf ini 티읕 (tieut).', 'Its name is 티읕 (tieut).', '타 · 토 · 틀', 'ta, to, dan teul', 'ta, to, and teul', NULL, 9),
  ('fc2-10', 'f-consonants-2', 'character', 'ㅍ', 'p · pieup', 'Konsonan p', 'The p consonant', 'Lepaskan udara lebih kuat daripada ㅂ.', 'Release more air than with ㅂ.', 'Nama huruf ini 피읖 (pieup).', 'Its name is 피읖 (pieup).', '파 · 포 · 풀', 'pa, po, dan pul', 'pa, po, and pul', NULL, 10),

  ('fb-1', 'f-batchim', 'word', '한', 'han', 'Satu (bagian dari Korea)', 'One (part of Korea)', 'Mulai dengan h, lanjutkan a, lalu tutup dengan n.', 'Start with h, continue with a, and close with n.', 'ㄴ, ㅁ, dan ㅇ di akhir semuanya berbunyi seperti n atau ng yang lembut.', 'Final ㄴ, ㅁ, and ㅇ all sound like a soft n or ng.', '한국', 'hanguk · Korea', 'hanguk · Korea', NULL, 1),
  ('fb-2', 'f-batchim', 'word', '밥', 'bap', 'Nasi atau makanan', 'Rice or meal', 'Tutup dengan p yang singkat tanpa melepaskan udara.', 'Close with a short p without releasing air.', 'ㄱ, ㄷ, dan ㅂ di akhir bunyinya mengecil menjadi k, t, dan p.', 'Final ㄱ, ㄷ, and ㅂ shrink to k, t, and p.', '밥을 먹어요.', 'Saya makan.', 'I eat a meal.', 8, 2),
  ('fb-3', 'f-batchim', 'word', '물', 'mul', 'Air', 'Water', 'Bunyi ㄹ akhir terdengar singkat, di antara l dan r.', 'The final ㄹ is short and sounds close to l.', 'ㄹ di akhir membuat bunyi l yang lembut.', 'Final ㄹ makes a soft l sound.', '물을 마셔요.', 'Saya minum air.', 'I drink water.', 7, 3),

  ('c1g-1', 'c-1-greetings', 'word', '안녕하세요', 'annyeonghaseyo', 'Halo', 'Hello', 'Tekankan ritme secara merata: an-nyeong-ha-se-yo.', 'Keep an even rhythm: an-nyeong-ha-se-yo.', 'Ungkapan sopan yang aman digunakan hampir di semua situasi.', 'A polite greeting that is safe in almost any situation.', '안녕하세요, 선생님!', 'Halo, Guru!', 'Hello, teacher!', 1, 1),
  ('c1g-2', 'c-1-greetings', 'word', '감사합니다', 'gamsahamnida', 'Terima kasih', 'Thank you', 'Dalam ucapan alami, 합니다 terdengar mendekati hamnida.', 'In natural speech, 합니다 sounds close to hamnida.', 'Gunakan untuk mengucapkan terima kasih dengan sopan atau formal.', 'Use it to say thank you politely or formally.', '정말 감사합니다.', 'Terima kasih banyak.', 'Thank you very much.', 2, 2),
  ('c1g-3', 'c-1-greetings', 'sentence', '만나서 반가워요', 'mannaseo bangawoyo', 'Senang bertemu dengan Anda.', 'Nice to meet you.', 'Sambungkan 만나서 tanpa jeda panjang.', 'Connect 만나서 without a long pause.', 'Ungkapan sopan dan ramah setelah berkenalan.', 'A friendly polite expression after an introduction.', '저도 만나서 반가워요.', 'Saya juga senang bertemu dengan Anda.', 'Nice to meet you too.', NULL, 3),

  ('c2i-1', 'c-2-intro', 'sentence', '저는 학생입니다', 'jeoneun haksaengimnida', 'Saya seorang pelajar.', 'I am a student.', '입니다 diucapkan imnida karena perubahan bunyi alami.', '입니다 is pronounced imnida because of a natural sound change.', 'Pola 저는 ...입니다 adalah perkenalan formal yang sederhana.', 'The 저는 ...입니다 pattern is a simple formal introduction.', '저는 디온입니다.', 'Saya Dion.', 'I am Dion.', 13, 1),
  ('c2i-2', 'c-2-intro', 'sentence', '제 이름은 민지예요', 'je ireumeun minjiyeyo', 'Nama saya Minji.', 'My name is Minji.', '제 terdengar seperti "je", bukan "je-i".', '제 is one syllable, pronounced "je".', '제 berarti "milik saya" dalam bentuk sopan.', '제 is the polite form of "my".', '제 이름은 수진이에요.', 'Nama saya Sujin.', 'My name is Sujin.', NULL, 2),
  ('c2i-3', 'c-2-intro', 'word', '친구', 'chingu', 'Teman', 'Friend', 'ㄱ di tengah kata terdengar lebih dekat ke g.', 'The ㄱ in the middle sounds closer to g.', 'Kata benda umum untuk teman tanpa membedakan gender.', 'A common noun for a friend of any gender.', '민수는 제 친구예요.', 'Minsu adalah teman saya.', 'Minsu is my friend.', 6, 3),

  ('c3q-1', 'c-3-questions', 'sentence', '이름이 뭐예요?', 'ireumi mwoyeyo', 'Siapa namamu?', 'What is your name?', '뭐예요 mengalir sebagai mwo-ye-yo.', '뭐예요 flows as mwo-ye-yo.', 'Gunakan nama + 이/가 뭐예요? untuk menanyakan sesuatu.', 'Use noun + 이/가 뭐예요? to ask about something.', '이거 뭐예요?', 'Apa ini?', 'What is this?', NULL, 1),
  ('c3q-2', 'c-3-questions', 'sentence', '어디에 가요?', 'eodie gayo', 'Kamu pergi ke mana?', 'Where are you going?', '에 melekat pada 어디: eo-di-e.', 'Attach 에 to 어디: eo-di-e.', '어디에 가요? adalah pertanyaan sopan tentang tujuan.', '어디에 가요? is a polite question about a destination.', '학교에 가요.', 'Saya pergi ke sekolah.', 'I go to school.', NULL, 2),
  ('c3q-3', 'c-3-questions', 'sentence', '뭘 좋아해요?', 'mwol joahaeyo', 'Apa yang kamu suka?', 'What do you like?', '뭘 adalah bentuk pendek dari 무엇을.', '뭘 is a shortened form of 무엇을.', 'Gunakan 뭘 좋아해요? untuk menanyakan kesukaan.', 'Use 뭘 좋아해요? to ask about preferences.', '음악을 좋아해요.', 'Saya suka musik.', 'I like music.', NULL, 3),

  ('c4l-1', 'c-4-likes', 'sentence', '저는 음악을 좋아해요', 'jeoneun eumageul joahaeyo', 'Saya suka musik.', 'I like music.', '좋아해요 dibaca jo-a-hae-yo dengan empat ketukan ringan.', 'Read 좋아해요 as jo-a-hae-yo with four light beats.', 'Gunakan kata benda + 을/를 + 좋아해요 untuk menyatakan kesukaan.', 'Use noun + 을/를 + 좋아해요 to express a preference.', '저는 한국어를 좋아해요.', 'Saya suka Bahasa Korea.', 'I like Korean.', 16, 1),
  ('c4l-2', 'c-4-likes', 'sentence', '저는 커피를 안 좋아해요', 'jeoneun keopireul an joahaeyo', 'Saya tidak suka kopi.', 'I do not like coffee.', '안 diucapkan singkat tepat sebelum 좋아해요.', 'Say 안 briefly right before 좋아해요.', 'Letakkan 안 sebelum 좋아해요 untuk negasi sederhana.', 'Place 안 before 좋아해요 for simple negation.', '저는 매운 음식을 안 좋아해요.', 'Saya tidak suka makanan pedas.', 'I do not like spicy food.', NULL, 2),
  ('c4l-3', 'c-4-likes', 'sentence', '김치를 제일 좋아해요', 'gimchireul jeil joahaeyo', 'Saya paling suka kimchi.', 'I like kimchi the most.', '제일 berarti "paling".', '제일 means "the most".', 'Gunakan 제일 sebelum kata kerja untuk menekankan kesukaan.', 'Use 제일 before a verb to emphasize a preference.', '한국어를 제일 좋아해요.', 'Saya paling suka bahasa Korea.', 'I like Korean the most.', NULL, 3),

  ('c5d-1', 'c-5-dialogue', 'sentence', '안녕하세요! 만나서 반가워요.', 'annyeonghaseyo! mannaseo bangawoyo.', 'Halo! Senang bertemu dengan Anda.', 'Hello! Nice to meet you.', 'Ucapkan salam dulu, lalu sapa perkenalan.', 'Say the greeting first, then the meeting phrase.', 'Gabungkan salam dan ungkapan perkenalan dalam satu sapaan.', 'Combine the greeting and the meeting phrase in one exchange.', '안녕하세요! 저는 디온이에요.', 'Halo! Saya Dion.', 'Hello! I am Dion.', NULL, 1),
  ('c5d-2', 'c-5-dialogue', 'sentence', '저는 민지예요. 이름이 뭐예요?', 'jeoneun minjiyeyo. ireumi mwoyeyo', 'Saya Minji. Siapa namamu?', 'I am Minji. What is your name?', 'Perkenalkan nama, lalu balas dengan pertanyaan.', 'Introduce your name, then ask back.', 'Pola perkenalan singkat diikuti pertanyaan nama.', 'A short introduction followed by a name question.', '저는 수진이에요. 이름이 뭐예요?', 'Saya Sujin. Siapa namamu?', 'I am Sujin. What is your name?', NULL, 2),
  ('c5d-3', 'c-5-dialogue', 'sentence', '저는 디온이에요. 음악을 좋아해요.', 'jeoneun dionieyo. eumageul joahaeyo', 'Saya Dion. Saya suka musik.', 'I am Dion. I like music.', 'Kenalkan diri, lalu sebutkan kesukaanmu.', 'Introduce yourself, then share a preference.', 'Perkenalan singkat diikuti ungkapan kesukaan.', 'A short introduction followed by a preference.', '저는 민지예요. 영화를 좋아해요.', 'Saya Minji. Saya suka film.', 'I am Minji. I like movies.', NULL, 3),

  ('frv-1', 'f-remediation-vowels', 'character', 'ㅓ', 'eo', 'Vokal "eo" lagi', 'The vowel "eo" again', 'Buka rahang rileks; bunyinya di antara "o" dan "a".', 'Relax your jaw; the sound sits between "o" and "a".', 'Jangan bingung dengan ㅏ yang lebih terbuka.', 'Do not confuse it with the more open ㅏ.', '거 · 너 · 더', 'geo, neo, deo', 'geo, neo, deo', NULL, 1),
  ('frv-2', 'f-remediation-vowels', 'character', 'ㅡ', 'eu', 'Vokal "eu" lagi', 'The vowel "eu" again', 'Ratakan bibir dan tarik bunyi ke belakang mulut.', 'Flatten your lips and pull the sound back.', 'Berbeda dari ㅜ yang bibirnya bulat.', 'It differs from ㅜ, which rounds the lips.', '그 · 느 · 드', 'geu, neu, deu', 'geu, neu, deu', NULL, 2),

  ('frc1-1', 'f-remediation-consonants-1', 'character', 'ㄱ', 'g/k', 'Konsonan g/k lagi', 'The g/k consonant again', 'Di awal terdengar g lembut, di akhir k pendek.', 'Light g at the start, short k at the end.', 'Perhatikan posisinya dalam suku kata.', 'Notice its position within the syllable.', '가 · 국', 'ga, guk', 'ga, guk', NULL, 1),
  ('frc1-2', 'f-remediation-consonants-1', 'character', 'ㅅ', 's', 'Konsonan s lagi', 'The s consonant again', 'Di depan ㅣ mendekati "sy".', 'Before ㅣ it is closer to "sh".', 'Bandingkan 사 dan 시.', 'Compare 사 and 시.', '사 · 시', 'sa, si', 'sa, si', NULL, 2),

  ('frc2-1', 'f-remediation-consonants-2', 'character', 'ㄷ', 'd/t', 'Konsonan d/t lagi', 'The d/t consonant again', 'Di awal d ringan, di akhir t pendek.', 'Light d at the start, short t at the end.', 'Bandingkan dengan ㅌ yang berhembus.', 'Compare with ㅌ, which is aspirated.', '다 · 닫', 'da, dat', 'da, dat', NULL, 1),
  ('frc2-2', 'f-remediation-consonants-2', 'character', 'ㅂ', 'b/p', 'Konsonan b/p lagi', 'The b/p consonant again', 'Di awal b lembut, batchim p pendek.', 'Soft b at the start, short p as batchim.', 'Bandingkan dengan ㅍ yang berhembus.', 'Compare with ㅍ, which is aspirated.', '바 · 밥', 'ba, bap', 'ba, bap', NULL, 2),

  ('frb-1', 'f-remediation-batchim', 'word', '집', 'jip', 'Rumah', 'Home', 'Batchim ㅂ di akhir dilepas seperti p pendek.', 'Final ㅂ is released like a short p.', 'ㅈ dan ㅣ membentuk ji, lalu ㅂ menjadi batchim.', 'ㅈ and ㅣ form ji, then ㅂ becomes the batchim.', '집에 가요.', 'Saya pulang.', 'I go home.', 9, 1),
  ('frb-2', 'f-remediation-batchim', 'word', '강', 'gang', 'Sungai', 'River', 'ㅇ di akhir berbunyi ng.', 'Final ㅇ sounds like ng.', 'ㅇ diam di awal, tetapi ng di akhir.', 'ㅇ is silent at the start but ng at the end.', '강을 건너요.', 'Saya menyeberangi sungai.', 'I cross the river.', NULL, 2),

  ('frf-1', 'f-remediation-fluency', 'word', '물', 'mul', 'Air', 'Water', 'Gabungkan ㅁ + ㅜ + ㄹ menjadi satu blok.', 'Combine ㅁ + ㅜ + ㄹ into one block.', 'Baca bagian per bagian: m + u + l.', 'Read it in parts: m + u + l.', '물을 마셔요.', 'Saya minum air.', 'I drink water.', 7, 1),
  ('frf-2', 'f-remediation-fluency', 'word', '집', 'jip', 'Rumah', 'Home', 'Gabungkan ㅈ + ㅣ + ㅂ menjadi satu blok.', 'Combine ㅈ + ㅣ + ㅂ into one block.', 'Baca bagian per bagian: j + i + p.', 'Read it in parts: j + i + p.', '집에 가요.', 'Saya pulang.', 'I go home.', 9, 2),

  ('c6r-1', 'c-6-remediation', 'word', '안녕히 가세요', 'annyeonghi gaseyo', 'Selamat jalan', 'Goodbye', 'ㅎ pada 안녕히 terdengar lembut dalam ucapan cepat.', 'The ㅎ in 안녕히 is light in quick speech.', 'Ucapkan kepada orang yang pergi ketika Anda tetap tinggal.', 'Say this to the person leaving when you are staying.', '내일 봐요. 안녕히 가세요!', 'Sampai besok. Selamat jalan!', 'See you tomorrow. Goodbye!', NULL, 1),
  ('c6r-2', 'c-6-remediation', 'word', '안녕히 계세요', 'annyeonghi gyeseyo', 'Selamat tinggal (tetaplah baik)', 'Goodbye (please stay well)', '계세요 diucapkan gye-se-yo.', 'Say 계세요 as gye-se-yo.', 'Ucapkan ketika Anda pergi dan orang lain tetap tinggal.', 'Say it when you leave and the other person stays.', '다음에 봐요. 안녕히 계세요!', 'Sampai jumpa lagi. Selamat tinggal!', 'See you later. Goodbye!', NULL, 2);


