  ('ms-vowels', 'cv-v1', 'basic-vowels', 'Vokal dasar', 'Basic vowels', 'Kenali bentuk dan bunyi vokal Hangul yang penting.', 'Recognize the shapes and sounds of essential Hangul vowels.', 1),
  ('ms-consonants-1', 'cv-v1', 'first-consonants', 'Konsonan pertama', 'First consonants', 'Pelajari konsonan pertama dan bentuk blok suku kata.', 'Learn the first consonants and how syllable blocks form.', 2),
  ('ms-consonants-2', 'cv-v1', 'remaining-consonants', 'Konsonan lanjutan', 'More consonants', 'Lengkapi semua konsonan dasar Hangul.', 'Complete the full set of basic Hangul consonants.', 3),
  ('ms-batchim', 'cv-v1', 'batchim', 'Batchim', 'Final consonants', 'Pahami tujuh bunyi akhir dan peralihan suara dasar.', 'Master the seven final sounds and basic sound carryover.', 4),
