INSERT INTO curriculum_node_items (id, node_id, type, korean_text, romanization, translation_id, translation_en, pronunciation_id, pronunciation_en, explanation_id, explanation_en, example_ko, example_id, example_en, vocabulary_id, item_order) VALUES
  ('fv-1', 'f-vowels', 'character', 'ㅏ', 'a', 'Vokal "a"', 'The vowel "a"', 'Buka mulut dengan rileks seperti "a" pada kata "apa".', 'Open your mouth naturally, like "a" in "father".', 'Garis pendek mengarah ke kanan dan diletakkan di kanan konsonan.', 'The short stroke points right and sits to the right of a consonant.', '가 · 나 · 다', 'Bunyi a pada ga, na, dan da.', 'The a sound in ga, na, and da.', NULL, 1),
  ('fv-2', 'f-vowels', 'character', 'ㅓ', 'eo', 'Vokal "eo"', 'The vowel "eo"', 'Ucapkan bunyi di antara "o" dan "a" dengan rahang rileks.', 'Make an open "uh" sound with a relaxed jaw.', 'Garis pendek mengarah ke kiri dan diletakkan di kanan konsonan.', 'The short stroke points left and sits to the right of a consonant.', '거 · 너 · 더', 'Bunyi eo pada geo, neo, dan deo.', 'The eo sound in geo, neo, and deo.', NULL, 2),
  ('fv-3', 'f-vowels', 'character', 'ㅗ', 'o', 'Vokal "o"', 'The vowel "o"', 'Bulatkan bibir tanpa memanjangkan bunyinya.', 'Round your lips without stretching the sound.', 'Vokal horizontal ini diletakkan di bawah konsonan.', 'This horizontal vowel is placed below a consonant.', '고 · 노 · 도', 'Bunyi o pada go, no, dan do.', 'The o sound in go, no, and do.', NULL, 3),
  ('fv-4', 'f-vowels', 'character', 'ㅜ', 'u', 'Vokal "u"', 'The vowel "u"', 'Bulatkan bibir seperti mengucapkan "u".', 'Round your lips like the "oo" in "moon".', 'Garis pendek mengarah ke bawah dan diletakkan di bawah konsonan.', 'The short stroke points down and sits below a consonant.', '구 · 누 · 두', 'Bunyi u pada gu, nu, dan du.', 'The u sound in gu, nu, and du.', NULL, 4),
  ('fv-5', 'f-vowels', 'character', 'ㅣ', 'i', 'Vokal "i"', 'The vowel "i"', 'Tersenyum ringan dan ucapkan "i" dengan jelas.', 'Keep your lips slightly wide and say "ee".', 'Satu garis vertikal yang diletakkan di kanan konsonan.', 'A single vertical line placed to the right of a consonant.', '기 · 니 · 디', 'Bunyi i pada gi, ni, dan di.', 'The i sound in gi, ni, and di.', NULL, 5),
  ('fv-6', 'f-vowels', 'character', 'ㅑ', 'ya', 'Vokal "ya"', 'The vowel "ya"', 'Mulai dengan y ringan lalu lanjutkan ke bunyi a.', 'Begin with a light y and move into the a sound.', 'Dua garis pendek membedakan ㅑ dari ㅏ.', 'Two short strokes distinguish ㅑ from ㅏ.', '야 · 냐 · 랴', 'Bunyi ya pada ya, nya, dan rya.', 'The ya sound in ya, nya, and rya.', NULL, 6),
  ('fv-7', 'f-vowels', 'character', 'ㅕ', 'yeo', 'Vokal "yeo"', 'The vowel "yeo"', 'Mulai dengan y ringan lalu buka ke bunyi eo.', 'Begin with a light y and open into the eo sound.', 'Dua garis pendek mengarah ke kiri.', 'Two short strokes point to the left.', '여 · 녀 · 셔', 'Bunyi yeo pada yeo, nyeo, dan syeo.', 'The yeo sound in yeo, nyeo, and syeo.', NULL, 7),
  ('fv-8', 'f-vowels', 'character', 'ㅛ', 'yo', 'Vokal "yo"', 'The vowel "yo"', 'Bulatkan bibir dan awali dengan y singkat.', 'Round your lips and begin with a short y.', 'Dua garis di atas membedakan ㅛ dari ㅗ.', 'Two upper strokes distinguish ㅛ from ㅗ.', '요 · 교 · 쇼', 'Bunyi yo pada yo, gyo, dan syo.', 'The yo sound in yo, gyo, and syo.', NULL, 8),
  ('fv-9', 'f-vowels', 'character', 'ㅠ', 'yu', 'Vokal "yu"', 'The vowel "yu"', 'Awali dengan y lalu bulatkan bibir untuk u.', 'Begin with y, then round your lips for u.', 'Dua garis ke bawah membedakan ㅠ dari ㅜ.', 'Two downward strokes distinguish ㅠ from ㅜ.', '유 · 규 · 슈', 'Bunyi yu pada yu, gyu, dan syu.', 'The yu sound in yu, gyu, and syu.', NULL, 9),
  ('fv-10', 'f-vowels', 'character', 'ㅡ', 'eu', 'Vokal "eu"', 'The vowel "eu"', 'Ratakan bibir dan tarik bunyi dari bagian belakang mulut.', 'Keep your lips flat and form the sound toward the back of the mouth.', 'Vokal horizontal tunggal ini diletakkan di bawah konsonan.', 'This single horizontal vowel sits below a consonant.', '그 · 느 · 드', 'Bunyi eu pada geu, neu, dan deu.', 'The eu sound in geu, neu, and deu.', NULL, 10),
INSERT INTO curriculum_check_items (id, check_node_id, category, prompt_id, prompt_en, choices, answer, explanation_id, explanation_en, item_order) VALUES
  ('fcv-1', 'f-check-vowels', 'recognition', 'Manakah bentuk vokal "a"?', 'Which shape is the vowel "a"?', '[{"id":"a","label":"ㅏ"},{"id":"b","label":"ㅓ"},{"id":"c","label":"ㅗ"},{"id":"d","label":"ㅜ"}]', 'a', 'ㅏ adalah vokal dengan garis ke kanan.', 'ㅏ is the vowel whose stroke points right.', 1),
  ('fcv-2', 'f-check-vowels', 'recognition', 'Manakah bentuk vokal "eo"?', 'Which shape is the vowel "eo"?', '[{"id":"a","label":"ㅏ"},{"id":"b","label":"ㅓ"},{"id":"c","label":"ㅣ"},{"id":"d","label":"ㅡ"}]', 'b', 'ㅓ adalah vokal dengan garis ke kiri.', 'ㅓ is the vowel whose stroke points left.', 2),
  ('fcv-3', 'f-check-vowels', 'sound', 'Bunyi apakah ㅜ?', 'What sound does ㅜ make?', '[{"id":"a","label":"o"},{"id":"b","label":"u"},{"id":"c","label":"eu"},{"id":"d","label":"i"}]', 'b', 'ㅜ berbunyi seperti "u" atau "oo".', 'ㅜ sounds like "u" or "oo".', 3),
  ('fcv-4', 'f-check-vowels', 'sound', 'Bunyi apakah ㅡ?', 'What sound does ㅡ make?', '[{"id":"a","label":"a"},{"id":"b","label":"eo"},{"id":"c","label":"eu"},{"id":"d","label":"u"}]', 'c', 'ㅡ berbunyi "eu" dengan bibir rata.', 'ㅡ sounds like "eu" with flat lips.', 4),
